insert into natural_english_private.catalogue(module,senses,questions) values
('advanced-native-1451', '["phrase"]'::jsonb, '{"advanced-native-1451-v1-audio":{"type":"mc","answers":["她用冷靜合理的方式幫助討論。"],"options":["她要求團隊立即接受第一個想法。","她把最有信心同事的偏好，當作主要決定依據。","她用冷靜合理的方式幫助討論。","她只是把聲音提高，沒有比較方案。"]},"advanced-native-1451-v2-reply":{"type":"mc","answers":["Someone who listens before reacting would help.","We need a person who can compare the evidence calmly.","A patient person could keep the discussion focused.","Someone level-headed could help us think clearly."],"options":["Someone who listens before reacting would help.","We need a person who can compare the evidence calmly.","A patient person could keep the discussion focused.","Someone level-headed could help us think clearly."]},"advanced-native-1451-v1-scene":{"type":"mc","answers":["The leader gave a level-headed response."],"options":["The leader gave a level-headed response.","The leader decided before hearing any explanation.","The leader focused on blaming people rather than solving the problem."]},"advanced-native-1451-v1-contrast":{"type":"mc","answers":["未聽解釋便因一時怒氣作決定。"],"options":["感到失望，但仍耐心比較選項。","遇到分歧仍冷靜檢視資料。","未聽解釋便因一時怒氣作決定。"]},"advanced-native-1451-v1-branch":{"type":"mc","answers":["You can feel upset and still make a level-headed decision after a pause."],"options":["You can feel upset and still make a level-headed decision after a pause.","Wait until the feeling has completely passed before you begin looking at the facts.","Follow the most confident speaker for now and review the reasons later."]},"advanced-native-1451-v1-final":{"type":"open","answers":["The captain was level-headed and gave everyone time to calm down before discussing the match.","A level-headed response helped the team focus on specific problems rather than blame."],"options":[]}}'::jsonb),
('advanced-native-1452', '["phrase"]'::jsonb, '{"advanced-native-1452-v1-audio":{"type":"mc","answers":["性別是分配工作的主要依據。"],"options":["每人的興趣和時間都已先被詢問。","所有家人都自行選了工作。","作者是在建議其他家庭照同一性別模式分工。","性別是分配工作的主要依據。"]},"advanced-native-1452-v2-reply":{"type":"mc","answers":["Some members are excluded from tasks they would like to try.","The current system overlooks individual strengths.","The roles are handed out according to gender instead of skills.","We have not asked what each person can actually do."],"options":["Some members are excluded from tasks they would like to try.","The current system overlooks individual strengths.","The roles are handed out according to gender instead of skills.","We have not asked what each person can actually do."]},"advanced-native-1452-v1-scene":{"type":"mc","answers":["The duties are handed out according to gender."],"options":["The duties are chosen after comparing individual skills and preferences.","Every student has freely selected a task.","The duties are handed out according to gender."]},"advanced-native-1452-v1-contrast":{"type":"mc","answers":["先問技能、時間和意願，再按個人情況分配。"],"options":["不理個人差異，按性別安排角色。","只按性別決定誰做哪項工作。","先問技能、時間和意願，再按個人情況分配。"]},"advanced-native-1452-v1-branch":{"type":"mc","answers":["Saying roles are handed out according to gender describes the system; it does not necessarily approve of it."],"options":["Quote that description as support for keeping the same allocation without checking the wider argument.","Use the sentence to assign similar duties before asking about individual skills.","Saying roles are handed out according to gender describes the system; it does not necessarily approve of it."]},"advanced-native-1452-v1-final":{"type":"open","answers":["The duties are handed out according to gender, but we should ask about each member’s skills.","Roles should not be handed out according to gender alone. Members need a chance to express their preferences."],"options":[]}}'::jsonb),
('advanced-native-1453', '["phrase"]'::jsonb, '{"advanced-native-1453-v1-audio":{"type":"mc","answers":["兩人在爭權，沒有釐清分工。"],"options":["兩人在爭權，沒有釐清分工。","兩人已清楚同意各自責任。","兩人只是交換不同意見，沒有爭取控制。","兩人正比較各自工作效率，沒有爭論決策權。"]},"advanced-native-1453-v2-reply":{"type":"mc","answers":["Too much time goes into competing for authority.","The organisers are playing tug-of-war over control.","They keep disputing who should make each decision.","They have not agreed on their responsibilities."],"options":["Too much time goes into competing for authority.","The organisers are playing tug-of-war over control.","They keep disputing who should make each decision.","They have not agreed on their responsibilities."]},"advanced-native-1453-v1-scene":{"type":"mc","answers":["They are playing tug-of-war over control."],"options":["They are playing tug-of-war over control.","They have divided responsibilities clearly and respect each other’s role.","They are discussing a practical detail without competing for authority."]},"advanced-native-1453-v1-contrast":{"type":"mc","answers":["有不同方案，但尊重分工，願意按證據討論。"],"options":["有不同方案，但尊重分工，願意按證據討論。","把時間花在爭誰說了算，而不處理工作。","雙方都要獨掌決策，反覆否定對方權限。"]},"advanced-native-1453-v1-branch":{"type":"mc","answers":["They can disagree without playing tug-of-war over control if they respect the agreed roles."],"options":["Treat their different tool preferences as enough evidence that they are competing for authority.","Give one person the whole project before asking whether the agreed roles are being respected.","They can disagree without playing tug-of-war over control if they respect the agreed roles."]},"advanced-native-1453-v1-final":{"type":"open","answers":["They are playing tug-of-war over control instead of planning the publicity.","We need to stop playing tug-of-war over control and agree who decides each part of the event."],"options":[]}}'::jsonb),
('advanced-native-1454', '["phrase"]'::jsonb, '{"advanced-native-1454-v1-audio":{"type":"mc","answers":["小組認為延後是較合適的選擇。"],"options":["兩個方案在安全性上相同，小組只按習慣選擇。","小組認為延後是較合適的選擇。","小組認為延後就是較快完成活動的方法。","小組沒有比較任何風險就隨意決定。"]},"advanced-native-1454-v2-reply":{"type":"mc","answers":["I thought waiting would help me make the better call.","The missing information could change the risk.","I wanted to compare the options more carefully.","A quick choice might have overlooked an important fact."],"options":["I thought waiting would help me make the better call.","The missing information could change the risk.","I wanted to compare the options more carefully.","A quick choice might have overlooked an important fact."]},"advanced-native-1454-v1-scene":{"type":"mc","answers":["They made the better call."],"options":["They chose the quickest option even though another one fitted the safety needs better.","They made the better call.","They selected the familiar option before weighing the new risk information."]},"advanced-native-1454-v1-contrast":{"type":"mc","answers":["作決定的人已知道所有未來事情，結果必定完美。"],"options":["作決定的人已知道所有未來事情，結果必定完美。","作出相對較合適的決定。","判斷可以根據當時資訊。"]},"advanced-native-1454-v1-branch":{"type":"mc","answers":["We can make the better call with the information available and still face an unexpected problem."],"options":["We can make the better call with the information available and still face an unexpected problem.","Judge the earlier decision only by the unexpected outcome, not by what was known at the time.","Keep the same choice next time without comparing whether the new circumstances differ."]},"advanced-native-1454-v1-final":{"type":"open","answers":["Comparing transport and costs helped us make the better call about the venue.","We made the better call by choosing a place that suited the group’s needs."],"options":[]}}'::jsonb),
('advanced-native-1455', '["phrase"]'::jsonb, '{"advanced-native-1455-v1-audio":{"type":"mc","answers":["影響力較大的發言不一定有最多證據。"],"options":["較強勢發言者已用最多證據說服其他人。","會議先衡量安靜組員證據，才選擇強勢發言者方案。","影響力較大的發言不一定有最多證據。","安靜組員只是沒有發言，並未準備證據。"]},"advanced-native-1455-v2-reply":{"type":"mc","answers":["Useful evidence can come from someone who speaks less.","Everyone needs a fair chance to contribute.","A confident speaker may overlook another perspective.","The louder voice is not always the wisest one."],"options":["Useful evidence can come from someone who speaks less.","Everyone needs a fair chance to contribute.","A confident speaker may overlook another perspective.","The louder voice is not always the wisest one."]},"advanced-native-1455-v1-scene":{"type":"mc","answers":["They followed the louder voice rather than weighing all the evidence."],"options":["They gave every piece of evidence equal consideration.","The quietest member made the decision after all views were heard.","They followed the louder voice rather than weighing all the evidence."]},"advanced-native-1455-v1-contrast":{"type":"mc","answers":["那人的理由一定最好，其他意見不用檢查。"],"options":["那人的理由一定最好，其他意見不用檢查。","某人表達較強勢，較易被注意。","那個聲音可能在討論中有較大影響。"]},"advanced-native-1455-v1-branch":{"type":"mc","answers":["Let us examine the evidence rather than simply follow the louder voice."],"options":["Let us examine the evidence rather than simply follow the louder voice.","Give the confident speaker’s proposal priority before checking the quieter member’s data.","Ask the quieter member to wait until the main decision has been made before explaining the evidence."]},"advanced-native-1455-v1-final":{"type":"open","answers":["We should not follow only the louder voice. The quiet student has important data to share.","The louder voice can dominate, so we need to invite everyone to explain their evidence."],"options":[]}}'::jsonb),
('advanced-native-1456', '["phrase"]'::jsonb, '{"advanced-native-1456-v1-audio":{"type":"mc","answers":["故事把孩子和家族記憶連起來。"],"options":["孩子把故事當作自己的親身經歷，而非了解長輩過去。","祖母只記下故事留待以後，尚未和孩子分享。","孩子正了解其他家庭的新故事，而不是自家背景。","故事把孩子和家族記憶連起來。"]},"advanced-native-1456-v2-reply":{"type":"mc","answers":["They give families a reason to listen and talk together.","They may help old memories remain part of family life.","They can become a living bridge between generations.","They can connect children with experiences they did not live through."],"options":["They give families a reason to listen and talk together.","They may help old memories remain part of family life.","They can become a living bridge between generations.","They can connect children with experiences they did not live through."]},"advanced-native-1456-v1-scene":{"type":"mc","answers":["The shared practice is a living bridge between generations."],"options":["The relatives recorded the recipe for storage but did not share the activity with the children.","The shared practice is a living bridge between generations.","The children learnt only the recipe steps, without hearing the family stories behind them."]},"advanced-native-1456-v1-contrast":{"type":"mc","answers":["連結一旦建立，兩代便不可能再有不同觀點。"],"options":["讓過去記憶與現在生活有關。","連結一旦建立，兩代便不可能再有不同觀點。","透過人和持續習俗連繫不同世代。"]},"advanced-native-1456-v1-branch":{"type":"mc","answers":["A story can be a living bridge precisely because it connects different experiences."],"options":["Set the unfamiliar stories aside and choose only experiences the children already recognise.","Ask the older relative to list dates without giving time for the children’s questions.","A story can be a living bridge precisely because it connects different experiences."]},"advanced-native-1456-v1-final":{"type":"open","answers":["Repairing old toys together became a living bridge between the children and their grandfather’s past.","His stories created a living bridge between generations while they worked on the toys."],"options":[]}}'::jsonb),
('advanced-native-1457', '["phrase"]'::jsonb, '{"advanced-native-1457-v1-audio":{"type":"mc","answers":["部分記憶的細節逐漸不清楚。"],"options":["部分記憶的細節逐漸不清楚。","家人仍記得每個細節，只是很少找到聚會時間。","故事在少數人不斷核對下變得更準確。","家人刻意刪除不同版本，已議定一個更清晰的說法。"]},"advanced-native-1457-v2-reply":{"type":"mc","answers":["The stories may gradually feel less familiar.","The memories may fade at the edges.","Some names and details may become harder to recall.","Younger members may lose part of the context."],"options":["The stories may gradually feel less familiar.","The memories may fade at the edges.","Some names and details may become harder to recall.","Younger members may lose part of the context."]},"advanced-native-1457-v1-scene":{"type":"mc","answers":["The tradition is beginning to fade at the edges."],"options":["The family deliberately replaced the old meaning after a discussion.","The memories stayed clear, but the family changed when it celebrated.","The tradition is beginning to fade at the edges."]},"advanced-native-1457-v1-contrast":{"type":"mc","answers":["所有內容必定在同一瞬間全部消失。"],"options":["部分細節逐漸變模糊。","力量或鮮明程度慢慢減弱。","所有內容必定在同一瞬間全部消失。"]},"advanced-native-1457-v1-branch":{"type":"mc","answers":["It may fade at the edges without disappearing completely; sharing the stories could help."],"options":["Stop sharing the custom until someone can recover every missing detail.","Keep only the festival name and treat that as enough to preserve its meaning.","It may fade at the edges without disappearing completely; sharing the stories could help."]},"advanced-native-1457-v1-final":{"type":"open","answers":["The tradition may fade at the edges if we forget the stories behind the food.","Its meaning is beginning to fade at the edges, so we could ask older relatives to share what they remember."],"options":[]}}'::jsonb),
('advanced-native-1458', '["phrase"]'::jsonb, '{"advanced-native-1458-v1-audio":{"type":"mc","answers":["忙碌可能令家庭聚餐被擱下。"],"options":["家人正主動取消聚餐，改用他們更喜歡的相處方式。","忙碌可能令家庭聚餐被擱下。","家人已預先留好固定聚餐時間。","工作時間較以前縮短，聚餐已更頻密。"]},"advanced-native-1458-v2-reply":{"type":"mc","answers":["It could be lost in the rush of modern life.","Busy schedules can make us keep postponing it.","A regular plan helps us avoid forgetting it.","Making time shows that the shared habit still matters."],"options":["It could be lost in the rush of modern life.","Busy schedules can make us keep postponing it.","A regular plan helps us avoid forgetting it.","Making time shows that the shared habit still matters."]},"advanced-native-1458-v1-scene":{"type":"mc","answers":["The habit was lost in the rush of modern life."],"options":["The family kept meeting more regularly despite the busy schedule.","The habit was lost in the rush of modern life.","The family deliberately protected the habit in its calendar."]},"advanced-native-1458-v1-contrast":{"type":"mc","answers":["它證明所有現代人都不可能維持任何家庭習俗。"],"options":["忙碌可能令重要習慣被忽略。","仍可透過安排時間維持習慣。","它證明所有現代人都不可能維持任何家庭習俗。"]},"advanced-native-1458-v1-branch":{"type":"mc","answers":["A custom need not be lost in the rush of modern life if we make a small regular space for it."],"options":["Save the contact for one large annual event rather than a small regular call.","A custom need not be lost in the rush of modern life if we make a small regular space for it.","Postpone the family habit until the calendar becomes completely clear."]},"advanced-native-1458-v1-final":{"type":"open","answers":["Our weekly calls could be lost in the rush of modern life, so we should choose a regular time.","We do not want family calls to be lost in the rush of modern life. A short Sunday call would help."],"options":[]}}'::jsonb),
('advanced-native-1459', '["phrase"]'::jsonb, '{"advanced-native-1459-v1-audio":{"type":"mc","answers":["她保留原本相同字句。"],"options":["她刪去了一半指示。","她加入自己的新建議取代原文。","她保留原本相同字句。","她只說了大意，改用自己的字句。"]},"advanced-native-1459-v2-reply":{"type":"mc","answers":["Read the original wording without changing it.","Keep the same words and order.","Use the written message rather than a loose summary.","Repeat it word for word."],"options":["Read the original wording without changing it.","Keep the same words and order.","Use the written message rather than a loose summary.","Repeat it word for word."]},"advanced-native-1459-v1-scene":{"type":"mc","answers":["She repeated the instructions word for word."],"options":["She replaced the instructions with her own suggestions.","She repeated the instructions word for word.","She summarised only the main idea in her own words."]},"advanced-native-1459-v1-contrast":{"type":"mc","answers":["保留大意，但完全改用自己的字句。"],"options":["不改字句地重複一段短訊。","原字詞和次序完整相同。","保留大意，但完全改用自己的字句。"]},"advanced-native-1459-v1-branch":{"type":"mc","answers":["Repeating it word for word does not always show that you understand it."],"options":["Ask the learner to repeat the passage faster instead of explaining the idea in new words.","Repeating it word for word does not always show that you understand it.","Use the accurate recitation as the main evidence of understanding, before asking for an explanation."]},"advanced-native-1459-v1-final":{"type":"open","answers":["I passed on the instructions word for word without adding my own suggestions.","I read the short message word for word so the group heard the exact wording."],"options":[]}}'::jsonb),
('advanced-native-1460', '["phrase"]'::jsonb, '{"advanced-native-1460-v1-audio":{"type":"mc","answers":["大家在一段時間內暫時轉移注意。"],"options":["大家在一段時間內暫時轉移注意。","大家在飯前已處理好令自己擔心的事。","大家把工作交由別人負責，不再由自己處理。","大家整小時只是不斷討論工作壓力。"]},"advanced-native-1460-v2-reply":{"type":"mc","answers":["A relaxed conversation may give us some breathing space.","It can help us put everyday stress to one side for a while.","It gives us a break from thinking about work.","We can focus on enjoying one another’s company."],"options":["A relaxed conversation may give us some breathing space.","It can help us put everyday stress to one side for a while.","It gives us a break from thinking about work.","We can focus on enjoying one another’s company."]},"advanced-native-1460-v1-scene":{"type":"mc","answers":["They put everyday stress to one side during the meal."],"options":["They spent the meal planning how to delegate their work to someone else.","They put everyday stress to one side during the meal.","They settled the work problem before eating, so there was nothing left to return to."]},"advanced-native-1460-v1-contrast":{"type":"mc","answers":["它保證所有壓力來源已永久消失。"],"options":["暫時轉移對日常憂慮的注意。","休息後仍可回頭處理需要。","它保證所有壓力來源已永久消失。"]},"advanced-native-1460-v1-branch":{"type":"mc","answers":["You can put everyday stress to one side for a short break and return to the tasks later."],"options":["You can put everyday stress to one side for a short break and return to the tasks later.","Finish the whole task list before allowing yourself that short evening break.","Use the relaxed evening as a reason to leave the unfinished tasks without a return time."]},"advanced-native-1460-v1-final":{"type":"open","answers":["A short walk can help us put everyday stress to one side before we return to our tasks.","Let us put everyday stress to one side for half an hour and enjoy the walk."],"options":[]}}'::jsonb),
('advanced-native-1461', '["phrase"]'::jsonb, '{"advanced-native-1461-v1-audio":{"type":"mc","answers":["通話讓原本疏遠的親人重新親近。"],"options":["通話主要用來決定下次見面的交通安排。","親人保持同樣疏遠，沒有重新交流。","他們恢復親近後，才開始固定通話。","通話讓原本疏遠的親人重新親近。"]},"advanced-native-1461-v2-reply":{"type":"mc","answers":["A relaxed conversation can make it easier to reconnect.","Showing up regularly can rebuild a little trust.","They may mend small distances between them.","They give people time to become familiar again."],"options":["A relaxed conversation can make it easier to reconnect.","Showing up regularly can rebuild a little trust.","They may mend small distances between them.","They give people time to become familiar again."]},"advanced-native-1461-v1-scene":{"type":"mc","answers":["Their visits helped mend small distances."],"options":["Their visits helped mend small distances.","Their visits left them just as reluctant to share as before.","They had already restored their closeness before the visits began."]},"advanced-native-1461-v1-contrast":{"type":"mc","answers":["旅客只在比較兩條路線的公里數，沒有談人際關係。"],"options":["表兄妹固定聯絡，慢慢恢復親近。","旅客只在比較兩條路線的公里數，沒有談人際關係。","親人透過談話減少小誤會。"]},"advanced-native-1461-v1-branch":{"type":"mc","answers":["A visit may mend small distances, but a serious conflict could need more time and honest discussion."],"options":["Use the first friendly visit as the reason to stop discussing the unresolved disagreement.","Arrange one long visit before asking whether both people are ready to talk openly.","A visit may mend small distances, but a serious conflict could need more time and honest discussion."]},"advanced-native-1461-v1-final":{"type":"open","answers":["Our weekly walks helped mend small distances after a long period of little contact.","Sharing everyday news can mend small distances between my cousin and me."],"options":[]}}'::jsonb),
('advanced-native-1462', '["phrase"]'::jsonb, '{"advanced-native-1462-v1-audio":{"type":"mc","answers":["問候保留形式，卻缺少真實關心。"],"options":["大家仔細聆聽，並照回應提供幫助。","大家改以實際幫助表達關心，不再使用口頭問候。","問候保留形式，卻缺少真實關心。","問候只因使用舊詞而被認為陌生，並非缺少聆聽。"]},"advanced-native-1462-v2-reply":{"type":"mc","answers":["People ask the question but ignore the answer.","The familiar words no longer lead to any real engagement.","It feels like a duty completed without much care.","It has become an empty ritual rather than a real conversation."],"options":["People ask the question but ignore the answer.","The familiar words no longer lead to any real engagement.","It feels like a duty completed without much care.","It has become an empty ritual rather than a real conversation."]},"advanced-native-1462-v1-scene":{"type":"mc","answers":["The words risk becoming empty rituals."],"options":["The words are followed by careful listening and practical help.","The family has stopped using any familiar greeting.","The words risk becoming empty rituals."]},"advanced-native-1462-v1-contrast":{"type":"mc","answers":["每年做同樣簡單活動，大家仍投入並珍惜其意義。"],"options":["只為完成程序說關心，之後不聽對方。","照例問候，但完全不在意回應。","每年做同樣簡單活動，大家仍投入並珍惜其意義。"]},"advanced-native-1462-v1-branch":{"type":"mc","answers":["Repeated customs need not be empty rituals if people still understand and value them."],"options":["Spend more on the ceremony before asking what participants still value about it.","Repeated customs need not be empty rituals if people still understand and value them.","Replace the annual gathering simply because its format is familiar."]},"advanced-native-1462-v1-final":{"type":"open","answers":["Our weekly greetings have become empty rituals because we never listen to the new members.","We should listen to people’s difficulties so our welcomes do not become empty rituals."],"options":[]}}'::jsonb),
('advanced-native-1463', '["phrase"]'::jsonb, '{"advanced-native-1463-v1-audio":{"type":"mc","answers":["聯絡方式改變，維持親近的目的仍在。"],"options":["新方式已讓家人減少私下交流，主要分享公開消息。","聯絡方式改變，維持親近的目的仍在。","聯絡目的改變，但方式完全沒變。","家人換了聯絡方式，也把保持親近改成只傳達安排。"]},"advanced-native-1463-v2-reply":{"type":"mc","answers":["The wrapping has changed, but its purpose can remain.","People can use a new method to express the same care.","A different format does not automatically remove the old value.","What matters is whether the shared meaning survives."],"options":["The wrapping has changed, but its purpose can remain.","People can use a new method to express the same care.","A different format does not automatically remove the old value.","What matters is whether the shared meaning survives."]},"advanced-native-1463-v1-scene":{"type":"mc","answers":["The wrapping has changed, but the care is still there."],"options":["The greetings have a new purpose, not merely a new format.","The wrapping has changed, but the care is still there.","The family still uses paper cards, but now sends only practical instructions."]},"advanced-native-1463-v1-contrast":{"type":"mc","answers":["活動形式和目的都與以前相同，沒有任何改動。"],"options":["改用短片，仍表達相同祝福。","改在線上聚會，仍用心分享家族故事。","活動形式和目的都與以前相同，沒有任何改動。"]},"advanced-native-1463-v1-branch":{"type":"mc","answers":["The wrapping has changed, but we should ask whether the original meaning is still being shared."],"options":["Restore the old format first and ask about the continuing meaning afterwards.","Choose the new format for convenience without discussing which purpose needs to remain.","The wrapping has changed, but we should ask whether the original meaning is still being shared."]},"advanced-native-1463-v1-final":{"type":"open","answers":["The wrapping has changed, but our birthday wishes are just as personal on a video call.","The wrapping has changed from a shared room to a screen, while our family memories remain important."],"options":[]}}'::jsonb),
('advanced-native-1464', '["phrase"]'::jsonb, '{"advanced-native-1464-v1-audio":{"type":"mc","answers":["慶祝被安排得像現成商業產品。"],"options":["慶祝被安排得像現成商業產品。","慶祝主要由家人按個別回憶設計，服務只作輔助。","價目表仍在比較，家人尚未挑選服務。","說話者想拒絕付費服務，而非只描述這次活動的感受。"]},"advanced-native-1464-v2-reply":{"type":"mc","answers":["We spent more time buying features than sharing memories.","It felt like an event package, with every part picked from a catalogue.","We followed a standard plan without adding our own family customs.","The choices seemed designed for customers rather than our family."],"options":["We spent more time buying features than sharing memories.","It felt like an event package, with every part picked from a catalogue.","We followed a standard plan without adding our own family customs.","The choices seemed designed for customers rather than our family."]},"advanced-native-1464-v1-scene":{"type":"mc","answers":["The celebration felt like an event package."],"options":["The celebration felt like an event package.","The celebration was shaped entirely by the family’s own memories.","The family had not selected any activities yet."]},"advanced-native-1464-v1-contrast":{"type":"mc","answers":["所有購買套裝的人都不關心家人。"],"options":["可能有一組預先安排的服務。","所有購買套裝的人都不關心家人。","活動可被當作方便選購的產品。"]},"advanced-native-1464-v1-branch":{"type":"mc","answers":["An event package can provide practical help while you keep the parts that matter to your family."],"options":["An event package can provide practical help while you keep the parts that matter to your family.","Keep the standard programme unchanged and leave out the grandmother’s stories to match the package.","Reject the useful booking service before checking whether the package can include family choices."]},"advanced-native-1464-v1-final":{"type":"open","answers":["The birthday party feels like an event package, so we could add time for family memories.","We can use an event package and still make the celebration personal by sharing our own stories."],"options":[]}}'::jsonb