('advanced-native-1482', '["phrase"]'::jsonb, '{"advanced-native-1482-v1-audio":{"type":"mc","answers":["聚會可能保留形式，卻失去真實感情。"],"options":["聚會可能保留形式，卻失去真實感情。","只要聚會出席人數減少，就表示家人已不再關心。","只要按程序完成聚會，就已足以證明家人真心投入。","說話者認為聚會人數增加就已恢復親近。"]},"advanced-native-1482-v2-reply":{"type":"mc","answers":["People may care more when the plan reflects what they enjoy together.","If the reunion feels forced, the heart can easily go out of it.","A choice gives people a reason to become personally involved.","I want the meeting to feel warm rather than like a duty."],"options":["People may care more when the plan reflects what they enjoy together.","If the reunion feels forced, the heart can easily go out of it.","A choice gives people a reason to become personally involved.","I want the meeting to feel warm rather than like a duty."]},"advanced-native-1482-v1-scene":{"type":"mc","answers":["When a gathering becomes a duty, the heart can easily go out of it."],"options":["When a gathering becomes a duty, the heart can easily go out of it.","The gathering still feels warm simply because everyone attends.","Everyone is already sharing personal memories with renewed enthusiasm."]},"advanced-native-1482-v1-contrast":{"type":"mc","answers":["活動規模較小，但大家仍真誠分享並珍惜相聚。"],"options":["聚會變成責任，家人開始失去交流的意願。","活動只剩勉強完成的形式，參與者不再投入。","活動規模較小，但大家仍真誠分享並珍惜相聚。"]},"advanced-native-1482-v1-branch":{"type":"mc","answers":["A reunion can keep its routine while the heart can easily go out of it if nobody feels involved."],"options":["A reunion can keep its routine while the heart can easily go out of it if nobody feels involved.","Use the completed programme as the main evidence that people still feel close.","Add more compulsory activities before asking which parts family members value."]},"advanced-native-1482-v1-final":{"type":"open","answers":["If the anniversary evening becomes only a duty, the heart can easily go out of it. We could invite members to share their own memories.","The evening needs personal involvem