('advanced-native-1487', '["phrase"]'::jsonb, '{"advanced-native-1487-v1-audio":{"type":"mc","answers":["部分學生很快失去投入，因為無法跟上術語。"],"options":["學生雖安靜但正仔細記錄術語的解釋。","學生已跟上術語，只在最後一段感到疲累。","學生先聽完整段講解，再討論不同看法。","部分學生很快失去投入，因為無法跟上術語。"]},"advanced-native-1487-v2-reply":{"type":"mc","answers":["A short explanation can make the later discussion easier.","It gives newcomers a useful starting point.","Some listeners may switch off straight away if the opening feels impossible to follow.","I want people to understand the examples from the start."],"options":["A short explanation can make the later discussion easier.","It gives newcomers a useful starting point.","Some listeners may switch off straight away if the opening feels impossible to follow.","I want people to understand the examples from the start."]},"advanced-native-1487-v1-scene":{"type":"mc","answers":["They switch off straight away."],"options":["They switch off straight away.","They remain engaged and ask for an explanation.","They follow the opening but lose focus only near the end."]},"advanced-native-1487-v1-contrast":{"type":"mc","answers":["學生安靜地做筆記，之後提出相關問題。"],"options":["學生安靜地做筆記，之後提出相關問題。","聽眾一聽到不明術語就不再投入。","開場後立即走神，不再跟內容。"]},"advanced-native-1487-v1-branch":{"type":"mc","answers":["They may be thinking; check understanding before saying they switch off straight away."],"options":["Use the pause alone to decide that the students have stopped following the lesson.","Speed up the explanation before checking whether they need time to process it.","They may be thinking; check understanding before saying they switch off straight away."]},"advanced-native-1487-v1-final":{"type":"open","answers":["New students may switch off straight away if we start with unfamiliar abbreviations. Let us explain the key terms first.","If the introduction is hard to follow, newcomers could switch off straight away. A simple example may help them stay engaged."],"options":[]}}'::jsonb),
