('advanced-native-1497', '["phrase"]'::jsonb, '{"advanced-native-1497-v1-audio":{"type":"mc","answers":["廣泛原則被收窄成不容個別選擇的要求。"],"options":["廣泛原則被收窄成不容個別選擇的要求。","家人正以多種可行路線實踐重視教育的原則。","家人只在討論一項可自由拒絕的課程建議。","家人不再重視教育，改以不相關活動作主要目標。"]},"advanced-native-1497-v2-reply":{"type":"mc","answers":["We may need to distinguish the shared aim from one preferred method.","Values harden into narrow expectations if we turn them into one fixed route for everyone.","A broad principle can be interpreted in different practical ways.","It helps us see whether people still have meaningful choices."],"options":["We may need to distinguish the shared aim from one preferred method.","Values harden into narrow expectations if we turn them into one fixed route for everyone.","A broad principle can be interpreted in different practical ways.","It helps us see whether people still have meaningful choices."]},"advanced-native-1497-v1-scene":{"type":"mc","answers":["Values harden into narrow expectations when responsibility is reduced to that single route."],"options":["The family is offering several ways to show responsibility.","The career is only one option that the child may freely compare with others.","Values harden into narrow expectations when responsibility is reduced to that single route."]},"advanced-native-1497-v1-contrast":{"type":"mc","answers":["共同原則仍容許不同而合理的實踐方式。"],"options":["一種偏好做法被當作證明重視家人的唯一途徑。","同一價值被解作人人必須同一職業。","共同原則仍容許不同而合理的實踐方式。"]},"advanced-native-1497-v1-branch":{"type":"mc","answers":["We can keep the principle but should notice when values harden into narrow expectations that rule out other worthwhile routes."],"options":["We can keep the principle but should notice when values harden into narrow expectations that rule out other worthwhile routes.","Remove the shared principle before exploring other ways to put it into practice.","Keep the single career route but describe it with a broader value word."]},"advanced-native-1497-v1-final":{"type":"open","answers":["Values h