('advanced-native-1499', '["phrase"]'::jsonb, '{"advanced-native-1499-v1-audio":{"type":"mc","answers":["期望限制了她探索其他可行路線。"],"options":["家人已根據她的新需要擴大選擇名單。","她先比較各種路線，再自行選定名單上的課程。","期望限制了她探索其他可行路線。","期望只是提供幾個可自由比較的例子。"]},"advanced-native-1499-v2-reply":{"type":"mc","answers":["The child may struggle to explore a suitable alternative.","It can make it harder to discuss changing interests honestly.","A fixed plan may overlook new strengths that appear later.","The expectation may become a cage rather than useful guidance."],"options":["The child may struggle to explore a suitable alternative.","It can make it harder to discuss changing interests honestly.","A fixed plan may overlook new strengths that appear later.","The expectation may become a cage rather than useful guidance."]},"advanced-native-1499-v1-scene":{"type":"mc","answers":["The rules have become a cage."],"options":["The rules have become a cage.","The rules have opened several new ways to contribute.","Members have chosen the fixed roles after freely trying alternatives."]},"advanced-native-1499-v1-contrast":{"type":"mc","answers":["指引提供清楚起點，也容許按需要調整。"],"options":["期望令一個人不敢探索適合自己的新方向。","規則阻擋合理替代方案。","指引提供清楚起點，也容許按需要調整。"]},"advanced-native-1499-v1-branch":{"type":"mc","answers":["A shared requirement need not become a cage if people have reasonable ways to meet it."],"options":["A shared requirement need not become a cage if people have reasonable ways to meet it.","Remove the common goal before asking whether several methods could meet it.","Keep one fixed method and rename it a choice without allowing alternatives."]},"advanced-native-1499-v1-final":{"type":"open","answers":["The fixed layout has become a cage for new ideas. We should allow different designs that meet the basic requirements.","The class rule should not become a cage. Students need room to test their own ideas while keeping the shared goal."],"options":[]}}'::jsonb),
